template vector <char> awh::Crypto::decrypt(const string &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования данных из буфера с выводом результата в буфер
 *
 */
template vector <char> awh::Crypto::decrypt(const vector <char> &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования данных из бинарного буфера с выводом результата в буфер
 *
 */
template vector <char> awh::Crypto::decrypt(const vector <uint8_t> &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования данных из строки с выводом результата в бинарный буфер
 *
 */
template vector <uint8_t> awh::Crypto::decrypt(const string &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования данных из буфера с выводом результата в бинарный буфер
 *
 */
template vector <uint8_t> awh::Crypto::decrypt(const vector <char> &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования данных из бинарного буфера с выводом результата в бинарный буфер
 *
 */
template vector <uint8_t> awh::Crypto::decrypt(const vector <uint8_t> &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Шаблон метода декодирования
 *
 * @tparam T тип возвращаемого результата
 *
 */
template <typename T>
/**
 * @brief Метод декодирования
 *
 * @param buffer буфер данных для шифрования
 * @param size   размер данных для шифрования
 * @param result буфер, куда следует положить результат
 * @param hash   тип хэш-суммы
 * @param cipher тип шифрования (BASE64, AES128, AES192, AES256)
 * @return       признак успешно выполненной работы
 *
 */
bool awh::Crypto::decrypt(const void * buffer, const size_t size, T & result, const hash_t hash, const cipher_t cipher) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	/**
	 * Признак работы выводится наружу отдельно от буфера: пустой буфер отказом
	 * не является - расшифровка сообщения, октетов не имеющего (4.9), даёт
	 * пустой открытый текст, - и судить по нему об удаче нельзя
	 */
	// Признак успешно выполненной работы
	bool outcome = false;
	// Затираем и очищаем буфер результата
	driver::wipe(result);
	/**
	 * Пустое сообщение работой принимается: в режиме с проверкой подлинности
	 * у него есть шифротекст - вектор инициализации и имитовставка, а потоковый
	 * путь пустое сообщение принимал и прежде. Отказ по одному лишь нулевому
	 * размеру расходил one-shot с потоком
	 */
	// Если буфер данных не передан, а размер его заявлен
	if((buffer == nullptr) && (size > 0)){
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Data buffer is not passed while its size is declared as %zu octets", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash), static_cast <uint16_t> (cipher)), log_t::flag_t::CRITICAL, size);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Data buffer is not passed while its size is declared as %zu octets", log_t::flag_t::CRITICAL, size);
		#endif
		// Выходим из метода с признаком отказа
		return outcome;
	}
	// Если буфер данных передан
	if((buffer != nullptr) || (size == 0)){
		/**
		 * Состояние берётся изменяемой ссылкой: постоянство работы относится к
		 * самому объекту, а состояние потока живёт за указателем и его постоянством
		 * не связано - приведение постоянства здесь лишь скрывало это правило
		 */
		// Получаем состояние объекта
		state_t & state = (* this->_params.state);
		/**
		 * Тип шифрования и тип хэш-суммы берутся у заведённого контекста, когда
		 * самим вызовом они не заданы: потоковый режим держался на том, что метка
		 * незаданного шифрования совпадала с меткой AES256 по младшему октету, и
		 * работа после инициализации попадала в ветвь AES по совпадению значений.
		 * Теперь она попадает туда по существу - потому что контекст заведён
		 */
		// Признак работы поверх заведённого контекста потокового шифрования
		const bool stream = (state.ctx != nullptr);
		/**
		 * Доводы разбираются порознь, а не разом: незаданный берётся у потока,
		 * заданный с потоком сверяется (4.4). Прежде признаком потока служило
		 * незадание одного лишь типа шифрования, отчего правило применялось неровно -
		 * вызов с иной хэш-суммой и незаданным шифром признавался работой по потоку
		 * и хэш-сумму молча отбрасывал, а вызов со сходящимся шифром и незаданной
		 * хэш-суммой отвергался, хотя брать её у потока и следовало
		 */
		// Тип шифрования, которым выполняется работа
		const cipher_t actual = ((stream && (cipher == cipher_t::NONE)) ? state.cipher : cipher);
		// Тип хэш-суммы, которым выводится ключ шифрования
		const hash_t digest = ((stream && (hash == hash_t::NONE)) ? state.hash : hash);
		/**
		 * Определяем тип шифрования
		 */
		switch(static_cast <uint16_t> (actual)){
			// Если производится работы с BASE64
			case static_cast <uint16_t> (cipher_t::BASE64): {
				// Выполняем декодирование строки BASE64 и получаем признак успеха
				outcome = driver::hash(reinterpret_cast <const char *> (buffer), size, actual, event_t::DECODE, state, result, this->_log);
				// Если декодирование не вышло
				if(!outcome){
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Unable to extract data from BASE64 encoded digest of %zu octets", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (digest), static_cast <uint16_t> (actual)), log_t::flag_t::WARNING, size);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Unable to extract data from BASE64 encoded digest of %zu octets", log_t::flag_t::WARNING, size);
					#endif
				}
			} break;
			// Если производится работы с AES128
			case static_cast <uint16_t> (cipher_t::AES128):
			// Если производится работы с AES192
			case static_cast <uint16_t> (cipher_t::AES192):
			// Если производится работы с AES256
			case static_cast <uint16_t> (cipher_t::AES256): {
				/**
				 * Отказ определяется признаком работы, а не пустотой выхода: в потоке
				 * порция без выхода законна - контекст накапливает вектор инициализации
				 * либо удерживает хвост, - и звать её отказом значило бы засорять лог
				 * ложными предупреждениями. Пустой выход законен и у разовой работы:
				 * расшифровка пустого сообщения даёт пустой открытый текст
				 */
				// Если пароль установлен
				if(!this->_params.password.empty()){
					// Если контекст шифрования не создан
					if(state.ctx == nullptr){
						// Проверяем текущее состояние
						/**
						 * Режим блочного шифрования входит в сличение наравне с
						 * разрядностью и хэш-суммой: он задаёт длину вектора
						 * инициализации и наличие имитовставки, и полагаться тут на
						 * то, что установщик режима сбрасывает состояние сам, значит
						 * держать правильность на связи двух работ вместо одной
						 */
						if((state.hash != digest) || (state.cipher != actual) || (state.mode != this->_params.mode) || (state.rounds != this->_params.rounds)){
							// Если инициализация ключей не выполнена
							if(!driver::cipher(actual, this->_params.mode, digest, this->_params.password, this->_params.salt, this->_params.rounds, state, this->_log)){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Unable to initialize AES cipher for decoding data", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (digest), static_cast <uint16_t> (actual)), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Unable to initialize AES cipher for decoding data", log_t::flag_t::CRITICAL);
								#endif
								// Выходим из метода с признаком отказа
								return outcome;
							}
						}
						// Выполняем дешифрование данных
						outcome = driver::hash(reinterpret_cast <const char *> (buffer), size, actual, event_t::DECODE, state, result, this->_log);
					// Если контекст шифрования уже создан
					} else {
						/**
						 * Заведённый контекст потокового шифрования переопределить
						 * доводами вызова нельзя: разрядность и тип хэш-суммы задаются
						 * при инициализации потока и живут в самом контексте. Прежде
						 * доводы вызова здесь молча отбрасывались - работа думала, что
						 * расшифровывает одной разрядностью, а расшифровывала другой
						 */
						/**
						 * Довод, заданный вызывающей стороной, сверяется с контекстом и тогда,
						 * когда задан он один: вызов с иной хэш-суммой и незаданным шифром
						 * признавался работой поверх потока, и хэш-сумма его молча отбрасывалась -
						 * работа думала, что вывела ключ одной хэш-суммой, а вывела другой.
						 * Незаданные доводы берутся из потока по-прежнему (4.4)
						 */
						// Признак расхождения доводов вызова с заведённым контекстом
						const bool mismatch = (stream &&
						                       (((cipher != cipher_t::NONE) && (cipher != state.cipher)) ||
						                        ((hash != hash_t::NONE) && (hash != state.hash))));
						// Если доводы вызова расходятся с заведённым контекстом
						if(mismatch){
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Cipher of the call does not match the one the stream was initialized with", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (digest), static_cast <uint16_t> (actual)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Cipher of the call does not match the one the stream was initialized with", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Выполняем дешифрование данных
						outcome = driver::hash(reinterpret_cast <const char *> (buffer), size, state.cipher, event_t::DECODE, state, result, this->_log);
					}
				/**
				 * Пустой пароль отвергается своей записью в лог наравне с заведением
				 * потока: прежде разовая работа выводила лишь общий отказ, и причину
				 * его - незаданный пароль - было не отличить от прочих
				 */
				// Если пароль шифрования не установлен
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Password of the cipher is not set", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (digest), static_cast <uint16_t> (actual)), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Password of the cipher is not set", log_t::flag_t::CRITICAL);
					#endif
					// Выходим из метода с признаком отказа, причина уже названа
					return outcome;
				}
				// Если дешифрование не вышло
				if(!outcome){
					// Не возвращаем зашифрованные данные: при неудаче дешифрования результат остаётся пустым
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Unable to decrypt data from AES", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (digest), static_cast <uint16_t> (actual)), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Unable to decrypt data from AES", log_t::flag_t::WARNING);
					#endif
				}
			} break;
			// Если тип шифрования не установлен либо разбору не знаком
			default: {
				/**
				 * Тип шифрования, разбору не знакомый, отвергается явно: прежде
				 * отбор шёл по младшему октету значения, а разрядность AES256 в него
				 * не умещается - его метка совпадала с меткой незаданного шифрования,
				 * и работа без шифрования уходила в ветвь AES
				 */
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Unable to decrypt data, cipher type is not set", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (digest), static_cast <uint16_t> (actual)), log_t::flag_t::WARNING);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Unable to decrypt data, cipher type is not set", log_t::flag_t::WARNING);
				#endif
			} break;
		}
	}
	// Выводим признак успешно выполненной работы
	return outcome;
}
/**
 * @brief Явный специализированный шаблон метода декодирования с выводом результата в строку
 *
 */
template bool awh::Crypto::decrypt(const void *, const size_t, string &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования с выводом результата в буфер
 *
 */
template bool awh::Crypto::decrypt(const void *, const size_t, vector <char> &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования с выводом результата в бинарный буфер
 *
 */
template bool awh::Crypto::decrypt(const void *, const size_t, vector <uint8_t> &, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Шаблон метода декодирования
 *
 * @tparam T тип возвращаемого результата
 *
 */
template <typename T>
/**
 * @brief Метод декодирования
 *
 * @details Работа выводит один лишь буфер: пустой буфер отказом не является, и
 *          если удачу работы нужно различать, следует брать перегрузку с
 *          признаком работы.
 *
 * @param buffer буфер данных для шифрования
 * @param size   размер данных для шифрования
 * @param hash   тип хэш-суммы
 * @param cipher тип шифрования (BASE64, AES128, AES192, AES256)
 * @return       результат декодирования
 *
 */
auto awh::Crypto::decrypt(const void * buffer, const size_t size, const hash_t hash, const cipher_t cipher) const noexcept -> T {
	// Переменная результата
	T result;
	// Выполняем работу, признак её отбрасывая
	this->decrypt <T> (buffer, size, result, hash, cipher);
	// Возвращаем результат работы функции
	return result;
}
/**
 * @brief Явный специализированный шаблон метода декодирования с выводом результата в строку
 *
 */
template string awh::Crypto::decrypt(const void *, const size_t, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования с выводом результата в буфер
 *
 */
template vector <char> awh::Crypto::decrypt(const void *, const size_t, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Явный специализированный шаблон метода декодирования с выводом результата в бинарный буфер
 *
 */
template vector <uint8_t> awh::Crypto::decrypt(const void *, const size_t, const hash_t, const cipher_t) const noexcept;
/**
 * @brief Метод генерации приватного ключа RSA
 *
 * @param size размер ключа в битах, от 2048 и выше (0 — по умолчанию)
 * @return     результат генерации ключа
 *
 */
bool awh::Crypto::generatePrivateKeyRSA(const size_t size) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		/**
		 * Разрядность ключа отвергается здесь, а не в глубине выработки: ключ
		 * короче двух тысяч разрядов стойкости не имеет, а незаданная разрядность
		 * означает разрядность по умолчанию, а не отказ
		 */
		// Разрядность вырабатываемого ключа
		const size_t bits = ((size == 0) ? AWH_CRYPTO_RSA_BITS : size);
		// Если разрядность ключа стойкости не имеет
		if(bits < AWH_CRYPTO_RSA_BITS){
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Private key size is too small to be secure", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Private key size is too small to be secure", log_t::flag_t::CRITICAL);
			#endif
			// Выходим из метода
			return result;
		}
		// Выполняем генерацию ключа RSA
		EVP_PKEY * privKey = ::EVP_RSA_gen(bits);
		// Если ключ не получен
		if(privKey == nullptr){
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Private key generation failed", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Private key generation failed", log_t::flag_t::CRITICAL);
			#endif
			// Возвращаем результат
			return result;
		}
		// Получаем ссылку на объект ключа RSA
		key_rsa_t & key = (* this->_params.key);
		/**
		 * Прежде заведённый ключ освобождается: запись нового поверх старого
		 * теряла его безвозвратно, тогда как установка ключа извне и загрузка
		 * его из файла освобождение выполняют
		 */
		// Если ключ RSA уже был заведён
		if(key.ctx != nullptr)
			// Освобождаем память выделенную под прежний ключ
			::EVP_PKEY_free(key.ctx);
		// Устанавливаем тип ключа
		key.type = key_type_t::PRIVATE;
		// Запоминаем приватный ключ
		key.ctx = privKey;
		// Формируем итоговый результат
		result = (key.ctx != nullptr);
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод получения публичного ключа RSA
 *
 * @return публичный ключ RSA
 *
 */
string awh::Crypto::getPublicKeyRSA() const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return "";
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	string result = "";
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Получаем ссылку на объект ключа RSA
		const key_rsa_t & key = (* this->_params.key);
		// Если ключ загружен
		if(key.ctx != nullptr){
			// Создаём объект BIO для записи публичного ключа
			BIO * bio = ::BIO_new(::BIO_s_mem());
			// Если объект BIO создан успешно
			if(bio != nullptr){
				/**
				 * Итог снимается с объекта BIO только по удавшейся выписке: отказ
				 * записи оставлял в объекте недописанную часть, и она уходила
				 * наружу непустым итогом - как будто ключ выписан целиком
				 */
				// Признак удавшейся выписки ключа
				bool exported = true;
				// Если файл не может быть записан
				if(::PEM_write_bio_PUBKEY(bio, key.ctx) != 1){
					// Снимаем признак удавшейся выписки ключа
					exported = false;
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Public key export failed", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Public key export failed", log_t::flag_t::CRITICAL);
					#endif
				}
				// Если выписка ключа удалась
				if(exported){
					// Получаем указатель на данные из объекта BIO
					char * buffer = nullptr;
					// Получаем размер данных из объекта BIO
					const size_t size = static_cast <size_t> (::BIO_get_mem_data(bio, &buffer));
					// Если данные получены успешно
					if((buffer != nullptr) && (size > 0))
						// Записываем данные в результат
						result.assign(buffer, size);
				}
				// Освобождаем объект BIO
				::BIO_free_all(bio);
			// Если объект BIO не создан
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Public key BIO creation failed", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Public key BIO creation failed", log_t::flag_t::CRITICAL);
				#endif
			}
		// Если путь к файлу не передан или публичный ключ не загружен
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Public key is not loaded", __PRETTY_FUNCTION__, {}, log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Public key is not loaded", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод установки публичного ключа RSA
 *
 * @param key публичный ключ RSA
 * @return    результат установки ключа
 *
 */
bool awh::Crypto::setPublicKeyRSA(string_view key) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Предел разрядности довода библиотеки криптографии отвергается и здесь:
	 * длина ключа приводится к знаковому 32-битному числу, и ключ свыше двух
	 * гигаоктетов разбирался бы по своей обрезанной части
	 */
	// Если публичный ключ передан и предела разрядности не превышает
	if(!key.empty() && (key.size() <= static_cast <size_t> (INT32_MAX))){
		/**
		 * Выполняем перехват ошибок
		 */
		try {
			// Выполняем парсинг ключа
			BIO * bio = ::BIO_new_mem_buf(key.data(), static_cast <int32_t> (key.size()));
			// Если объект BIO создан успешно
			if(bio != nullptr){
				// Читаем публичный ключ из буфера
				EVP_PKEY * pkey = ::PEM_read_bio_PUBKEY(bio, nullptr, nullptr, nullptr);
				// Освобождаем объект BIO
				::BIO_free(bio);
				// Если публичный ключ получен, оглашаем его разрядность
				if(pkey != nullptr)
					driver::strength(pkey, key_type_t::PUBLIC, this->_log);
				// Если публичный ключ получен
				if(pkey != nullptr){
					// Получаем ссылку на объект ключа RSA
					key_rsa_t & key = (* this->_params.key);
					// Если публичный ключ уже сгенерирован
					if(key.ctx != nullptr)
						// Освобождаем публичный ключ
						::EVP_PKEY_free(key.ctx);
					// Запоминаем публичный ключ
					key.ctx = pkey;
					// Устанавливаем тип ключа
					key.type = key_type_t::PUBLIC;
					// Формируем итоговый результат
					result = (key.ctx != nullptr);
				// Если публичный ключ не получен
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Public key import failed", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Public key import failed", log_t::flag_t::CRITICAL);
					#endif
				}
			// Если объект BIO не создан
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Public key BIO import failed", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Public key BIO import failed", log_t::flag_t::CRITICAL);
				#endif
			}
		/**
		 * Если возникает ошибка
		 */
		} catch(const exception & error) {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL, error.what());
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
			#endif
		}
	// Если ключ пуст либо предел разрядности превышает
	} else {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Public key is empty or its size exceeds the limit of the cryptography library", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Public key is empty or its size exceeds the limit of the cryptography library", log_t::flag_t::CRITICAL);
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод установки приватного ключа RSA
 *
 * @param key приватный ключ RSA
 * @return    результат установки ключа
 *
 */
bool awh::Crypto::setPrivateKeyRSA(string_view key) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Предел разрядности довода библиотеки криптографии отвергается и здесь:
	 * длина ключа приводится к знаковому 32-битному числу, и ключ свыше двух
	 * гигаоктетов разбирался бы по своей обрезанной части
	 */
	// Если приватный ключ передан и предела разрядности не превышает
	if(!key.empty() && (key.size() <= static_cast <size_t> (INT32_MAX))){
		/**
		 * Выполняем перехват ошибок
		 */
		try {
			// Выполняем парсинг ключа
			BIO * bio = ::BIO_new_mem_buf(key.data(), static_cast <int32_t> (key.size()));
			// Если объект BIO создан успешно
			if(bio != nullptr){
				// Читаем приватный ключ из буфера
				EVP_PKEY * pkey = ::PEM_read_bio_PrivateKey(bio, nullptr, &driver::password, reinterpret_cast <void *> (const_cast <string *> (&this->_params.passwordRSA)));
				// Освобождаем объект BIO
				::BIO_free(bio);
				// Если приватный ключ получен, оглашаем его разрядность
				if(pkey != nullptr)
					driver::strength(pkey, key_type_t::PRIVATE, this->_log);
				// Если приватный ключ получен
				if(pkey != nullptr){
					// Получаем ссылку на объект ключа RSA
					key_rsa_t & key = (* this->_params.key);
					// Если приватный ключ уже сгенерирован
					if(key.ctx != nullptr)
						// Освобождаем приватный ключ
						::EVP_PKEY_free(key.ctx);
					// Запоминаем приватный ключ
					key.ctx = pkey;
					// Устанавливаем тип ключа
					key.type = key_type_t::PRIVATE;
					// Формируем итоговый результат
					result = (key.ctx != nullptr);
				// Если приватный ключ не получен
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Private key import failed", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Private key import failed", log_t::flag_t::CRITICAL);
					#endif
				}
			// Если объект BIO не создан
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Private key BIO import failed", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Private key BIO import failed", log_t::flag_t::CRITICAL);
				#endif
			}
		/**
		 * Если возникает ошибка
		 */
		} catch(const exception & error) {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL, error.what());
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
			#endif
		}
	// Если ключ пуст либо предел разрядности превышает
	} else {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Private key is empty or its size exceeds the limit of the cryptography library", __PRETTY_FUNCTION__, make_tuple(key.size()), log_t::flag_t::CRITICAL);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Private key is empty or its size exceeds the limit of the cryptography library", log_t::flag_t::CRITICAL);
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод получения приватного ключа RSA
 *
 * @param cipher тип шифрования приватного ключа
 * @return       приватный ключ RSA
 *
 */
string awh::Crypto::getPrivateKeyRSA(const cipher_t cipher) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return "";
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	string result = "";
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Получаем ссылку на объект ключа RSA
		const key_rsa_t & key = (* this->_params.key);
		// Если ключ загружен
		if(key.ctx != nullptr){
			// Если ключ является приватным
			if(key.type == key_type_t::PRIVATE){
				// Создаём объект BIO для записи приватного ключа
				BIO * bio = ::BIO_new(::BIO_s_mem());
				// Если объект BIO создан успешно
				if(bio != nullptr){
					/**
					 * Итог снимается с объекта BIO только по удавшейся выписке: отказ
					 * записи оставлял в объекте недописанную часть, и она уходила
					 * наружу непустым итогом - как будто ключ выписан целиком
					 */
					// Признак удавшейся выписки ключа
					bool exported = true;
					// Если пароль защиты приватного ключа не установлен
					if(this->_params.passwordRSA.empty()){
						// Если файл не может быть записан
						if(::PEM_write_bio_PrivateKey(bio, key.ctx, nullptr, nullptr, 0, nullptr, nullptr) != 1){
							// Снимаем признак удавшейся выписки ключа
							exported = false;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Private key export failed", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Private key export failed", log_t::flag_t::CRITICAL);
							#endif
						}
					// Если пароль установлен
					} else {
						// Тип шифрования AES
						const EVP_CIPHER * evp = ::EVP_enc_null();
						/**
						 * Определяем длину шифрования
						 */
						switch(static_cast <uint16_t> (cipher)){
							// Устанавливаем шифрование в 128
							case static_cast <uint16_t> (cipher_t::AES128):
								// Устанавливаем функцию шифрования
								evp = ::EVP_aes_128_cbc();
							break;
							// Устанавливаем шифрование в 192
							case static_cast <uint16_t> (cipher_t::AES192):
								// Устанавливаем функцию шифрования
								evp = ::EVP_aes_192_cbc();
							break;
							// Устанавливаем шифрование в 256
							case static_cast <uint16_t> (cipher_t::AES256):
							// Разрядность шифрования по умолчанию равна наибольшей
							case static_cast <uint16_t> (cipher_t::NONE):
								// Устанавливаем функцию шифрования
								evp = ::EVP_aes_256_cbc();
							break;
							/**
							 * Тип шифрования, защите ключа не подходящий, отвергается явно: прежде
							 * он молча подменялся наибольшей разрядностью, и работа думала, что ключ
							 * защищён тем шифром, который она назвала
							 */
							// Если тип шифрования разбору не знаком
							default:
								// Снимаем функцию шифрования
								evp = nullptr;
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Cipher type is not suitable for private key protection", __PRETTY_FUNCTION__, make_tuple(static_cast <uint16_t> (cipher)), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Cipher type is not suitable for private key protection", log_t::flag_t::CRITICAL);
								#endif
						}
						// Если файл не может быть записан
						if((evp == nullptr) || (::PEM_write_bio_PKCS8PrivateKey(bio, key.ctx, evp, this->_params.passwordRSA.c_str(), static_cast <int32_t> (this->_params.passwordRSA.size()), nullptr, nullptr) != 1)){
							// Снимаем признак удавшейся выписки ключа
							exported = false;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Private key export failed", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Private key export failed", log_t::flag_t::CRITICAL);
							#endif
						}
					}
					// Если выписка ключа удалась
					if(exported){
						// Получаем указатель на данные из объекта BIO
						char * buffer = nullptr;
						// Получаем размер данных из объекта BIO
						const size_t size = static_cast <size_t> (::BIO_get_mem_data(bio, &buffer));
						// Если данные получены успешно
						if((buffer != nullptr) && (size > 0))
							// Записываем данные в результат
							result.assign(buffer, size);
					}
					/**
					 * Запись ключа в объекте ввода-вывода гасится прежде освобождения:
					 * освобождение содержимого не гасит, и приватный ключ - в открытом
					 * ли виде, под защитой ли паролем - оставался лежать в памяти до тех
					 * пор, покуда её не выдадут кому-то ещё. Гасится и при отказе
					 * выписки: та могла успеть выписать часть.
					 *
					 * Выданная наружу запись тайной распоряжается уже вызывающий: строку
					 * ему выдали, и гасить её - его дело
					 */
					// Указатель на запись ключа в объекте ввода-вывода
					char * written = nullptr;
					// Получаем размер записи ключа в объекте ввода-вывода
					const size_t length = static_cast <size_t> (::BIO_get_mem_data(bio, &written));
					// Если запись ключа в объекте ввода-вывода есть
					if((written != nullptr) && (length > 0))
						// Выполняем затирание записи ключа
						::OPENSSL_cleanse(written, length);
					// Освобождаем объект BIO
					::BIO_free_all(bio);
				// Если объект BIO не создан
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Private key BIO creation failed", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Private key BIO creation failed", log_t::flag_t::CRITICAL);
					#endif
				}
			// Если ключ не является приватным
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Key cannot be export because it is not private", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Key cannot be export because it is not private", log_t::flag_t::CRITICAL);
				#endif
			}
		// Если ключ не загружен
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Private key is not loaded", __PRETTY_FUNCTION__, {}, log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Private key is not loaded", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод загрузки публичного ключа RSA из файла
 *
 * @param path путь к файлу с публичным ключом
 * @return     результат загрузки ключа
 *
 */
bool awh::Crypto::loadPublicKeyRSA(string_view path) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Если путь к файлу передан правильно
		if(!path.empty()){
			/**
			 * Для операционной системы MS Windows
			 */
			#if _WIN32 || _WIN64
				// Открываем файл с публичным ключом
				FILE * file = ::_wfopen(this->_fmk->convert(path).c_str(), L"rb");
				// Если файл открыт удачно
				if(file != nullptr){
					// Читаем публичный ключ из файла
					EVP_PKEY * pkey = ::PEM_read_PUBKEY(file, nullptr, nullptr, nullptr);
					// Закрываем файл
					::fclose(file);
					// Если публичный ключ получен, оглашаем его разрядность
					if(pkey != nullptr)
						driver::strength(pkey, key_type_t::PUBLIC, this->_log);
					// Если публичный ключ получен
					if(pkey != nullptr){
						// Получаем ссылку на объект ключа RSA
						key_rsa_t & key = (* this->_params.key);
						// Если публичный ключ уже сгенерирован
						if(key.ctx != nullptr)
							// Освобождаем публичный ключ
							::EVP_PKEY_free(key.ctx);
						// Запоминаем публичный ключ
						key.ctx = pkey;
						// Устанавливаем тип ключа
						key.type = key_type_t::PUBLIC;
						// Формируем итоговый результат
						result = (key.ctx != nullptr);
					// Если публичный ключ не получен
					} else {
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Public key reading failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Public key reading failed", log_t::flag_t::CRITICAL);
						#endif
					}
				// Если файл не открыт
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Public key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Public key file opening failed", log_t::flag_t::WARNING);
					#endif
				}
			/**
			 * Для других операционных систем
			 */
			#else
				// Открываем файл с публичным ключом
				/**
				 * Путь снимается в свою строку: обозрение строки завершающего нуля
				 * не обещает, и подача его указателя открывала бы не тот файл либо
				 * уводила чтение за границу обозреваемого
				 */
				// Имя файла, завершающим нулём оканчивающееся
				const string filename(path);
				FILE * file = ::fopen(filename.c_str(), "rb");
				// Если файл открыт удачно
				if(file != nullptr){
					// Читаем публичный ключ из файла
					EVP_PKEY * pkey = ::PEM_read_PUBKEY(file, nullptr, nullptr, nullptr);
					// Закрываем файл
					::fclose(file);
					// Если публичный ключ получен, оглашаем его разрядность
					if(pkey != nullptr)
						driver::strength(pkey, key_type_t::PUBLIC, this->_log);
					// Если публичный ключ получен
					if(pkey != nullptr){
						// Получаем ссылку на объект ключа RSA
						key_rsa_t & key = (* this->_params.key);
						// Если публичный ключ уже сгенерирован
						if(key.ctx != nullptr)
							// Освобождаем публичный ключ
							::EVP_PKEY_free(key.ctx);
						// Запоминаем публичный ключ
						key.ctx = pkey;
						// Устанавливаем тип ключа
						key.type = key_type_t::PUBLIC;
						// Формируем итоговый результат
						result = (key.ctx != nullptr);
					// Если публичный ключ не получен
					} else {
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Public key reading failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Public key reading failed", log_t::flag_t::CRITICAL);
						#endif
					}
				// Если файл не открыт
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Public key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Public key file opening failed", log_t::flag_t::WARNING);
					#endif
				}
			#endif
		// Если путь к файлу не передан
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid path for public key", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid path for public key", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод загрузки приватного ключа RSA из файла
 *
 * @param path путь к файлу с приватным ключом
 * @return     результат загрузки ключа
 *
 */
bool awh::Crypto::loadPrivateKeyRSA(string_view path) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Если путь к файлу передан правильно
		if(!path.empty()){
			/**
			 * Для операционной системы MS Windows
			 */
			#if _WIN32 || _WIN64
				// Открываем файл с приватным ключом
				FILE * file = ::_wfopen(this->_fmk->convert(path).c_str(), L"rb");
				// Если файл открыт удачно
				if(file != nullptr){
					// Читаем приватный ключ из файла
					EVP_PKEY * pkey = ::PEM_read_PrivateKey(file, nullptr, &driver::password, reinterpret_cast <void *> (const_cast <string *> (&this->_params.passwordRSA)));
					// Закрываем файл
					::fclose(file);
					// Если приватный ключ получен, оглашаем его разрядность
					if(pkey != nullptr)
						driver::strength(pkey, key_type_t::PRIVATE, this->_log);
					// Если приватный ключ получен
					if(pkey != nullptr){
						// Получаем ссылку на объект ключа RSA
						key_rsa_t & key = (* this->_params.key);
						// Если приватный ключ уже сгенерирован
						if(key.ctx != nullptr)
							// Освобождаем приватный ключ
							::EVP_PKEY_free(key.ctx);
						// Запоминаем приватный ключ
						key.ctx = pkey;
						// Устанавливаем тип ключа
						key.type = key_type_t::PRIVATE;
						// Формируем итоговый результат
						result = (key.ctx != nullptr);
					// Если публичный ключ не получен
					} else {
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Private key reading failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Private key reading failed", log_t::flag_t::CRITICAL);
						#endif
					}
				// Если файл не открыт
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Private key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Private key file opening failed", log_t::flag_t::WARNING);
					#endif
				}
			/**
			 * Для других операционных систем
			 */
			#else
				/**
				 * Путь снимается в свою строку: обозрение строки завершающего нуля
				 * не обещает, и подача его указателя открывала бы не тот файл либо
				 * уводила чтение за границу обозреваемого
				 */
				// Имя файла, завершающим нулём оканчивающееся
				const string filename(path);
				// Открываем файл с приватным ключом
				FILE * file = ::fopen(filename.c_str(), "rb");
				// Если файл открыт удачно
				if(file != nullptr){
					// Читаем приватный ключ из файла
					EVP_PKEY * pkey = ::PEM_read_PrivateKey(file, nullptr, &driver::password, reinterpret_cast <void *> (const_cast <string *> (&this->_params.passwordRSA)));
					// Закрываем файл
					::fclose(file);
					// Если приватный ключ получен, оглашаем его разрядность
					if(pkey != nullptr)
						driver::strength(pkey, key_type_t::PRIVATE, this->_log);
					// Если приватный ключ получен
					if(pkey != nullptr){
						// Получаем ссылку на объект ключа RSA
						key_rsa_t & key = (* this->_params.key);
						// Если приватный ключ уже сгенерирован
						if(key.ctx != nullptr)
							// Освобождаем приватный ключ
							::EVP_PKEY_free(key.ctx);
						// Запоминаем приватный ключ
						key.ctx = pkey;
						// Устанавливаем тип ключа
						key.type = key_type_t::PRIVATE;
						// Формируем итоговый результат
						result = (key.ctx != nullptr);
					// Если публичный ключ не получен
					} else {
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Private key reading failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Private key reading failed", log_t::flag_t::CRITICAL);
						#endif
					}
				// Если файл не открыт
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Private key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Private key file opening failed", log_t::flag_t::WARNING);
					#endif
				}
			#endif
		// Если путь к файлу не передан
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid path for private key", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid path for private key", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод сохранения публичного ключа RSA в файл
 *
 * @param path путь к файлу для сохранения публичного ключа
 * @return     результат сохранения ключа
 *
 */
bool awh::Crypto::savePublicKeyRSA(string_view path) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Получаем ссылку на объект ключа RSA
		const key_rsa_t & key = (* this->_params.key);
		// Если путь к файлу передан правильно
		if(!path.empty() && (key.ctx != nullptr)){
			/**
			 * Для операционной системы MS Windows
			 */
			#if _WIN32 || _WIN64
				// Сохраняем публичный ключ
				FILE * file = ::_wfopen(this->_fmk->convert(path).c_str(), L"wb");
				// Если файл открыт удачно
				if(file != nullptr){
					// Если файл не может быть записан
					if(!(result = (::PEM_write_PUBKEY(file, key.ctx) == 1))){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Public key saving failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Public key saving failed", log_t::flag_t::CRITICAL);
						#endif
					}
					// Закрываем файл
					::fclose(file);
					/**
					 * Файл, записанный не до конца, снимается тем же порядком, что и у
					 * приватного ключа: наполовину выписанный ключ ключом не является.
					 * Записи через отдельный файл с переименованием здесь нет - её
					 * пробел записан решением 5.29 вместе с правами доступа
					 */
					// Если запись ключа не удалась
					if(!result)
						// Удаляем файл, записанный не до конца
						::_wremove(this->_fmk->convert(path).c_str());
				// Если файл не открыт
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Public key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Public key file opening failed", log_t::flag_t::WARNING);
					#endif
				}
			/**
			 * Для других операционных систем
			 */
			#else
				// Сохраняем публичный ключ
				/**
				 * Путь снимается в свою строку: обозрение строки завершающего нуля
				 * не обещает, и подача его указателя открывала бы не тот файл либо
				 * уводила чтение за границу обозреваемого
				 */
				// Имя файла, завершающим нулём оканчивающееся
				const string filename(path);
				/**
				 * Ключ выписывается в отдельный файл и ставится на место
				 * переименованием, тем же порядком, что и приватный: запись прямо в
				 * конечный файл усекает прежний ключ первым же открытием, и отказ
				 * выписки оставлял бы вызывающего вовсе без ключа
				 */
				// Имя отдельного файла, в который ключ выписывается
				const string temporary(filename + ".tmp");
				FILE * file = ::fopen(temporary.c_str(), "wb");
				// Если файл открыт удачно
				if(file != nullptr){
					// Если файл не может быть записан
					if(!(result = (::PEM_write_PUBKEY(file, key.ctx) == 1))){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Public key saving failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Public key saving failed", log_t::flag_t::CRITICAL);
						#endif
					}
					/**
					 * Запись доводится до носителя прежде закрытия файла тем же
					 * порядком, что и у приватного ключа (5.33)
					 */
					// Если довести запись файла до носителя не удалось
					if(result && ((::fflush(file) != 0) || (::fsync(::fileno(file)) != 0))){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Public key file syncing failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Public key file syncing failed", log_t::flag_t::CRITICAL);
						#endif
						// Запоминаем признак отказа работы
						result = false;
					}
					// Закрываем файл
					::fclose(file);
					// Если запись ключа удалась
					if(result){
						// Если поставить записанный ключ на место не удалось
						if(::rename(temporary.c_str(), filename.c_str()) != 0){
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Public key file renaming failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Public key file renaming failed", log_t::flag_t::CRITICAL);
							#endif
							// Удаляем файл, на место не ставший
							::remove(temporary.c_str());
							// Запоминаем признак отказа работы
							result = false;
						// Если довести запись каталога до носителя не удалось
						} else if(!driver::settled(filename)){
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Public key folder syncing failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Public key folder syncing failed", log_t::flag_t::WARNING);
							#endif
						}
					// Если запись ключа не удалась, снимаем файл, записанный не до конца
					} else ::remove(temporary.c_str());
				// Если файл не открыт
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Public key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Public key file opening failed", log_t::flag_t::WARNING);
					#endif
				}
			#endif
		// Если путь к файлу не передан или публичный ключ не загружен
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid path or public key is not loaded", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid path or public key is not loaded", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод сохранения приватного ключа RSA в файл
 *
 * @param path   путь к файлу для сохранения приватного ключа
 * @param cipher тип шифрования приватного ключа
 * @return       результат сохранения ключа
 *
 */
bool awh::Crypto::savePrivateKeyRSA(string_view path, const cipher_t cipher) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Получаем ссылку на объект ключа RSA
		const key_rsa_t & key = (* this->_params.key);
		// Если путь к файлу передан правильно
		if(!path.empty() && (key.ctx != nullptr)){
			// Если ключ является приватным
			if(key.type == key_type_t::PRIVATE){
				/**
				 * Тип шифрования защиты разбирается прежде открытия файла: открытие
				 * усекает прежний файл сразу, а негодный тип отвергался уже после -
				 * годный ключ, на диске лежавший, погибал от вызова, который и работы
				 * не начал. Разбор здесь лишь отвергает; сам шифр выбирается ниже,
				 * где он и надобен
				 */
				// Если пароль защиты приватного ключа установлен
				if(!this->_params.passwordRSA.empty()){
					/**
					 * Определяем пригодность типа шифрования
					 */
					switch(static_cast <uint16_t> (cipher)){
						// Если тип шифрования защите ключа подходит
						case static_cast <uint16_t> (cipher_t::NONE):
						case static_cast <uint16_t> (cipher_t::AES128):
						case static_cast <uint16_t> (cipher_t::AES192):
						case static_cast <uint16_t> (cipher_t::AES256):
						break;
						// Если тип шифрования разбору не знаком
						default: {
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Cipher type is not suitable for private key protection", __PRETTY_FUNCTION__, make_tuple(static_cast <uint16_t> (cipher)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Cipher type is not suitable for private key protection", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return result;
						}
					}
				}
				/**
				 * Для операционной системы MS Windows
				 */
				#if _WIN32 || _WIN64
					// Сохраняем приватный ключ
					FILE * file = ::_wfopen(this->_fmk->convert(path).c_str(), L"wb");
					// Если файл открыт удачно
					if(file != nullptr){
						// Если пароль защиты приватного ключа не установлен
						if(this->_params.passwordRSA.empty()){
							// Если файл не может быть записан
							if(!(result = (::PEM_write_PrivateKey(file, key.ctx, nullptr, nullptr, 0, nullptr, nullptr) == 1))){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Private key saving failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Private key saving failed", log_t::flag_t::CRITICAL);
								#endif
							}
						// Если пароль установлен
						} else {
							// Тип шифрования AES
							const EVP_CIPHER * evp = ::EVP_enc_null();
							/**
							 * Определяем длину шифрования
							 */
							switch(static_cast <uint16_t> (cipher)){
								// Устанавливаем шифрование в 128
								case static_cast <uint16_t> (cipher_t::AES128):
									// Устанавливаем функцию шифрования
									evp = ::EVP_aes_128_cbc();
								break;
								// Устанавливаем шифрование в 192
								case static_cast <uint16_t> (cipher_t::AES192):
									// Устанавливаем функцию шифрования
									evp = ::EVP_aes_192_cbc();
								break;
								// Устанавливаем шифрование в 256
								case static_cast <uint16_t> (cipher_t::AES256):
								// Разрядность шифрования по умолчанию равна наибольшей
								case static_cast <uint16_t> (cipher_t::NONE):
									// Устанавливаем функцию шифрования
									evp = ::EVP_aes_256_cbc();
								break;
								/**
								 * Тип шифрования, защите ключа не подходящий, отвергается явно: прежде
								 * он молча подменялся наибольшей разрядностью, и работа думала, что ключ
								 * защищён тем шифром, который она назвала
								 */
								// Если тип шифрования разбору не знаком
								default:
									// Снимаем функцию шифрования
									evp = nullptr;
									/**
									 * Если включён режим отладки
									 */
									#if DEBUG_MODE
										// Записываем ошибку в лог
										this->_log->debug("Cipher type is not suitable for private key protection", __PRETTY_FUNCTION__, make_tuple(static_cast <uint16_t> (cipher)), log_t::flag_t::CRITICAL);
									/**
									 * Если режим отладки не включён
									 */
									#else
										// Записываем ошибку в лог
										this->_log->print("Cipher type is not suitable for private key protection", log_t::flag_t::CRITICAL);
									#endif
							}
							// Если файл не может быть записан
							if((evp == nullptr) || !(result = (::PEM_write_PKCS8PrivateKey(file, key.ctx, evp, this->_params.passwordRSA.c_str(), static_cast <int32_t> (this->_params.passwordRSA.size()), nullptr, nullptr) == 1))){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Private key saving failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Private key saving failed", log_t::flag_t::CRITICAL);
								#endif
							}
						}
						// Закрываем файл
						::fclose(file);
						/**
						 * Файл, записанный не до конца, снимается тем же порядком, что
						 * и у прочих операционных систем: наполовину выписанный ключ
						 * ключом не является, а лежит он под тем же именем, под которым
						 * вызывающий ждёт годный
						 */
						// Если запись ключа не удалась
						if(!result)
							// Удаляем файл, записанный не до конца
							::_wremove(this->_fmk->convert(path).c_str());
					// Если файл не открыт
					} else {
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Private key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Private key file opening failed", log_t::flag_t::WARNING);
						#endif
					}
				/**
				 * Для других операционных систем
				 */
				#else
					/**
					 * Путь снимается в свою строку: обозрение строки завершающего нуля
					 * не обещает, и подача его указателя открывала бы не тот файл либо
					 * уводила чтение за границу обозреваемого
					 */
					// Имя файла, завершающим нулём оканчивающееся
					const string filename(path);
					/**
					 * Ключ выписывается в отдельный файл, а на место его ставится
					 * переименованием. Запись прямо в конечный файл усекает прежний
					 * ключ первым же открытием, и всякий отказ письма - негодный тип
					 * шифрования, отказ самой выписки, нехватка места - оставлял бы
					 * вызывающего вовсе без ключа: прежний уничтожен, новый не
					 * записан. Переименование же в пределах одной файловой системы
					 * неделимо: до него на месте лежит прежний ключ, после - новый,
					 * и промежутка между ними нет
					 */
					// Имя отдельного файла, в который ключ выписывается
					const string temporary(filename + ".tmp");
					/**
					 * Файл заводится правами на чтение и запись одному лишь владельцу:
					 * обычное открытие берёт права у маски создания, а та у многих
					 * дозволяет чтение всем, и приватный ключ ложился бы на диск
					 * доступным любому в системе. Права задаются при самом заведении,
					 * а не правкой после: между заведением и правкой файл был бы
					 * доступен, и того довольно
					 */
					// Заводим файл приватного ключа правами владельца
					const int32_t fd = ::open(temporary.c_str(), O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
					/**
					 * Права, поданные открытию, берутся им лишь при заведении нового
					 * файла: перезапись прежнего усекает его содержимое, а права
					 * оставляет как есть, и ключ ложился бы в файл, доступный всем.
					 * Оттого права ставятся ещё и снятому дескриптору - к этой поре
					 * файл усечён и ключа в нём нет, а стало быть открытым он не
					 * побывал
					 */
					// Если файл заведён, ставим права владельца и перезаписанному файлу
					if((fd >= 0) && (::fchmod(fd, S_IRUSR | S_IWUSR) != 0)){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Private key file rights setting failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Private key file rights setting failed", log_t::flag_t::CRITICAL);
						#endif
						// Закрываем заведённый файловый дескриптор
						::close(fd);
						// Удаляем файл, ключа не получивший
						::remove(temporary.c_str());
						// Выходим из метода с признаком отказа
						return result;
					}
					// Сохраняем приватный ключ
					FILE * file = ((fd < 0) ? nullptr : ::fdopen(fd, "wb"));
					/**
					 * Заведённый файл снимается и здесь: отказ открытия потока записи
					 * оставлял на диске пустой файл под именем отдельного, а снятие его
					 * стояло лишь у отказа правки прав. Файл этот вызывающему не нужен
					 * и убран быть должен всяким путём отказа
					 */
					// Если файл заведён, но поток записи по нему не открылся
					if((fd >= 0) && (file == nullptr)){
						// Закрываем заведённый файловый дескриптор
						::close(fd);
						// Удаляем файл, ключа не получивший
						::remove(temporary.c_str());
					}
					// Если файл открыт удачно
					if(file != nullptr){
						// Если пароль защиты приватного ключа не установлен
						if(this->_params.passwordRSA.empty()){
							// Если файл не может быть записан
							if(!(result = (::PEM_write_PrivateKey(file, key.ctx, nullptr, nullptr, 0, nullptr, nullptr) == 1))){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Private key saving failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Private key saving failed", log_t::flag_t::CRITICAL);
								#endif
							}
						// Если пароль установлен
						} else {
							// Тип шифрования AES
							const EVP_CIPHER * evp = ::EVP_enc_null();
							/**
							 * Определяем длину шифрования
							 */
							switch(static_cast <uint16_t> (cipher)){
								// Устанавливаем шифрование в 128
								case static_cast <uint16_t> (cipher_t::AES128):
									// Устанавливаем функцию шифрования
									evp = ::EVP_aes_128_cbc();
								break;
								// Устанавливаем шифрование в 192
								case static_cast <uint16_t> (cipher_t::AES192):
									// Устанавливаем функцию шифрования
									evp = ::EVP_aes_192_cbc();
								break;
								// Устанавливаем шифрование в 256
								case static_cast <uint16_t> (cipher_t::AES256):
								// Разрядность шифрования по умолчанию равна наибольшей
								case static_cast <uint16_t> (cipher_t::NONE):
									// Устанавливаем функцию шифрования
									evp = ::EVP_aes_256_cbc();
								break;
								/**
								 * Тип шифрования, защите ключа не подходящий, отвергается явно: прежде
								 * он молча подменялся наибольшей разрядностью, и работа думала, что ключ
								 * защищён тем шифром, который она назвала
								 */
								// Если тип шифрования разбору не знаком
								default:
									// Снимаем функцию шифрования
									evp = nullptr;
									/**
									 * Если включён режим отладки
									 */
									#if DEBUG_MODE
										// Записываем ошибку в лог
										this->_log->debug("Cipher type is not suitable for private key protection", __PRETTY_FUNCTION__, make_tuple(static_cast <uint16_t> (cipher)), log_t::flag_t::CRITICAL);
									/**
									 * Если режим отладки не включён
									 */
									#else
										// Записываем ошибку в лог
										this->_log->print("Cipher type is not suitable for private key protection", log_t::flag_t::CRITICAL);
									#endif
							}
							// Если файл не может быть записан
							if((evp == nullptr) || !(result = (::PEM_write_PKCS8PrivateKey(file, key.ctx, evp, this->_params.passwordRSA.c_str(), static_cast <int32_t> (this->_params.passwordRSA.size()), nullptr, nullptr) == 1))){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Private key saving failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Private key saving failed", log_t::flag_t::CRITICAL);
								#endif
							}
						}
						/**
						 * Запись доводится до носителя прежде закрытия файла: обрыв
						 * питания между переименованием и сбросом кэша оставил бы на
						 * месте прежнего ключа файл пустой либо недописанный
						 */
						// Если довести запись файла до носителя не удалось
						if(result && ((::fflush(file) != 0) || (::fsync(fd) != 0))){
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Private key file syncing failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Private key file syncing failed", log_t::flag_t::CRITICAL);
							#endif
							// Запоминаем признак отказа работы
							result = false;
						}
						// Закрываем файл
						::fclose(file);
						// Если запись ключа удалась
						if(result){
							// Если поставить записанный ключ на место не удалось
							if(::rename(temporary.c_str(), filename.c_str()) != 0){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Private key file renaming failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Private key file renaming failed", log_t::flag_t::CRITICAL);
								#endif
								// Удаляем файл, на место не ставший
								::remove(temporary.c_str());
								// Запоминаем признак отказа работы
								result = false;
							// Если довести запись каталога до носителя не удалось
							} else if(!driver::settled(filename)){
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Private key folder syncing failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Private key folder syncing failed", log_t::flag_t::WARNING);
								#endif
							}
						/**
						 * Файл, записанный не до конца, снимается: наполовину выписанный
						 * ключ ключом не является, а прежний, на месте лежащий, остаётся
						 * нетронутым - его этот вызов не касался вовсе
						 */
						// Если запись ключа не удалась
						} else ::remove(temporary.c_str());
					// Если файл не открыт
					} else {
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Private key file opening failed", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Private key file opening failed", log_t::flag_t::WARNING);
						#endif
					}
				#endif
			// Если ключ не является приватным
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Key cannot be saved because it is not private", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Key cannot be saved because it is not private", log_t::flag_t::CRITICAL);
				#endif
			}
		// Если путь к файлу не передан или приватный ключ не сгенерирован
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid path or private key is not generated", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid path or private key is not generated", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(path), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Метод шифрования данных публичным ключом RSA
 *
 * @param buffer буфер данных для шифрования
 * @param result буфер куда следует положить результат
 *
 */
bool awh::Crypto::encryptWithPublicKey(const vector <uint8_t> & buffer, vector <uint8_t> & result) const noexcept {
	// Вызываем метод шифрования данных публичным ключом RSA
	return this->encryptWithPublicKey(buffer.data(), buffer.size(), result);
}
/**
 * @brief Метод шифрования данных публичным ключом RSA
 *
 * @param buffer буфер данных для шифрования
 * @param size   размер данных для шифрования
 * @param result буфер куда следует положить результат
 *
 */
bool awh::Crypto::encryptWithPublicKey(const uint8_t * buffer, const size_t size, vector <uint8_t> & result) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	/**
	 * Буфер результата затирается и очищается на входе: отказ, случившийся до
	 * отведения буфера, оставлял в нём итог прежней работы - подпись прежних
	 * данных выглядела бы подписью нынешних. Затирается он наравне с буферами
	 * работы по симметричному ключу (4.18): очистка содержимого не гасит, а
	 * расшифровка ключом RSA держит в нём открытый текст
	 */
	// Затираем и очищаем буфер результата
	driver::wipe(result);
	/**
	 * Признак работы выводится наружу отдельно от буфера наравне с разовой
	 * работой по симметричному ключу (4.22): пустой буфер отказом не является,
	 * и судить по нему об удаче нельзя
	 */
	// Признак успешно выполненной работы
	bool outcome = false;
	/**
	 * Контекст библиотеки криптографии заводится в области работы целиком:
	 * заведён он внутри перехвата, и сбой отведения памяти после его заведения
	 * уносил бы работу мимо освобождения - контекст оставался бы висеть
	 */
	// Контекст работы с ключом
	EVP_PKEY_CTX * ctx = nullptr;
	/**
	 * Отсутствующий буфер при заявленном размере отвергается с записью в лог
	 * наравне с работой по симметричному ключу (4.27): молчаливый отказ не давал
	 * отличить негодный довод вызова от отказа самой работы
	 */
	// Если буфер данных не передан, а размер его заявлен
	if((buffer == nullptr) && (size > 0)){
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Data buffer is not passed while its size is declared as %zu octets", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL, size);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Data buffer is not passed while its size is declared as %zu octets", log_t::flag_t::CRITICAL, size);
		#endif
		// Выходим из метода с признаком отказа
		return outcome;
	}
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Если буфер данных и размер данных переданы правильно
		if((buffer != nullptr) || (size == 0)){
			// Получаем ссылку на объект ключа RSA
			const key_rsa_t & key = (* this->_params.key);
			// Если публичный ключ сгенерирован
			if(key.ctx != nullptr){
				// Создаём контекст для шифрования
				ctx = ::EVP_PKEY_CTX_new(key.ctx, nullptr);
				// Если контекст для подписи не создан
				if(ctx == nullptr){
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Context allocation failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Context allocation failed", log_t::flag_t::CRITICAL);
					#endif
				// Если контекст для подписи создан
				} else {
					// Если контекст для шифрования не инициализирован
					if((::EVP_PKEY_encrypt_init(ctx) <= 0) || (::EVP_PKEY_CTX_set_rsa_padding(ctx, RSA_PKCS1_OAEP_PADDING) <= 0) || (::EVP_PKEY_CTX_set_rsa_oaep_md(ctx, ::EVP_sha256()) <= 0) || (::EVP_PKEY_CTX_set_rsa_mgf1_md(ctx, ::EVP_sha256()) <= 0)){
						// Освобождаем контекст для шифрования
						::EVP_PKEY_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Encrypt init failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Encrypt init failed", log_t::flag_t::CRITICAL);
						#endif
						// Выходим из метода с признаком отказа
						return outcome;
					}
					// Размер подписи в байтах
					/**
					 * Дополнение OAEP отводит под себя две хэш-суммы и ещё два октета,
					 * и сообщение длиннее остатка ключом RSA не шифруется вовсе. Предел
					 * этот отвергается здесь, а не в глубине библиотеки: оттуда пришёл
					 * бы отказ без указания на настоящую причину и без самого предела
					 */
					// Определяем размер ключа RSA в октетах
					const size_t width = static_cast <size_t> (::EVP_PKEY_size(key.ctx));
					/**
					 * Ключ, под одно дополнение слишком короткий, отвергается до вычитания:
					 * разность считается беззнаковой, и у ключа короче 66 октетов - а такой
					 * приходит вводом со стороны, где разрядность не проверяется, - она
					 * обращалась в число огромное. Предел переставал отвергать что бы то ни
					 * было, и отказ приходил из глубины библиотеки без внятной причины
					 */
					// Если размер ключа RSA под одно дополнение OAEP недостаточен
					if(width <= ((2 * AWH_CRYPTO_OAEP_HASH_SIZE) + 2)){
						// Освобождаем контекст для шифрования
						::EVP_PKEY_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("RSA key of %zu octets is too short for OAEP padding, at least %zu octets are required", __PRETTY_FUNCTION__, make_tuple(width, static_cast <size_t> ((2 * AWH_CRYPTO_OAEP_HASH_SIZE) + 3)), log_t::flag_t::CRITICAL, width, static_cast <size_t> ((2 * AWH_CRYPTO_OAEP_HASH_SIZE) + 3));
						#else
							// Записываем ошибку в лог
							this->_log->print("RSA key of %zu octets is too short for OAEP padding, at least %zu octets are required", log_t::flag_t::CRITICAL, width, static_cast <size_t> ((2 * AWH_CRYPTO_OAEP_HASH_SIZE) + 3));
						#endif
						// Выходим из метода с признаком отказа
						return outcome;
					}
					// Определяем наибольший размер сообщения, ключом RSA шифруемого
					const size_t limit = (width - (2 * AWH_CRYPTO_OAEP_HASH_SIZE) - 2);
					// Если размер сообщения предел шифрования ключом RSA превышает
					if(size > limit){
						// Освобождаем контекст для шифрования
						::EVP_PKEY_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Message of %zu octets exceeds the limit of %zu octets for the RSA key in use", __PRETTY_FUNCTION__, make_tuple(size, limit), log_t::flag_t::CRITICAL, size, limit);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Message of %zu octets exceeds the limit of %zu octets for the RSA key in use", log_t::flag_t::CRITICAL, size, limit);
						#endif
						// Выходим из метода с признаком отказа
						return outcome;
					}
					size_t length = 0;
					// Получаем размер зашифрованных данных
					if(::EVP_PKEY_encrypt(ctx, nullptr, &length, buffer, size) <= 0){
						// Освобождаем контекст для шифрования
						::EVP_PKEY_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Get encrypted data size failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Get encrypted data size failed", log_t::flag_t::CRITICAL);
						#endif
						// Выходим из метода с признаком отказа
						return outcome;
					}
					// Затираем и очищаем буфер результата
					driver::wipe(result);
					// Выделяем память под подпись
					result.resize(length, 0);
					// Получаем зашифрованные данные
					if(::EVP_PKEY_encrypt(ctx, result.data(), &length, buffer, size) <= 0){
						/**
						 * Результат очищается: буфер под него уже отведён и заполнен нулями,
						 * и работа, судящая об удаче по его непустоте, приняла бы нули за
						 * готовый результат
						 */
						// Затираем и очищаем буфер результата
						driver::wipe(result);
						// Освобождаем контекст для шифрования
						::EVP_PKEY_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Encrypt data failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Encrypt data failed", log_t::flag_t::CRITICAL);
						#endif
						// Выходим из метода с признаком отказа
						return outcome;
					}
					// Изменяем размер буфера под фактический размер зашифрованных данных
					result.resize(length);
					// Запоминаем признак успешно выполненной работы
					outcome = true;
					// Освобождаем контекст для шифрования
					::EVP_PKEY_CTX_free(ctx);
					// Снимаем указатель освобождённого контекста
					ctx = nullptr;
				}
			// Если публичный ключ не сгенерирован или не загружен
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Public or private key is not generated", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::WARNING);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Public or private key is not generated", log_t::flag_t::WARNING);
				#endif
			}
		// Если буфер данных или размер данных переданы неправильно
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid buffer or size for encryption", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid buffer or size for encryption", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Буфер результата затирается наравне с прочими отказами (4.18, 5.11):
		 * сбой отведения памяти мог застать работу после того, как в буфер уже
		 * лёг открытый текст либо подпись
		 */
		// Затираем и очищаем буфер результата
		driver::wipe(result);
		// Если контекст работы с ключом заведён
		if(ctx != nullptr)
			// Освобождаем контекст работы с ключом
			::EVP_PKEY_CTX_free(ctx);
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Выводим признак успешно выполненной работы
	return outcome;
}
/**
 * @brief Метод дешифрования данных приватным ключом RSA
 *
 * @param buffer буфер данных для дешифрования
 * @param result буфер куда следует положить результат
 *
 */
bool awh::Crypto::decryptWithPrivateKey(const vector <uint8_t> & buffer, vector <uint8_t> & result) const noexcept {
	// Вызываем метод дешифрования данных приватным ключом RSA
	return this->decryptWithPrivateKey(buffer.data(), buffer.size(), result);
}
/**
 * @brief Метод дешифрования данных приватным ключом RSA
 *
 * @param buffer буфер данных для дешифрования
 * @param size   размер данных для дешифрования
 * @param result буфер куда следует положить результат
 *
 */
bool awh::Crypto::decryptWithPrivateKey(const uint8_t * buffer, const size_t size, vector <uint8_t> & result) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	/**
	 * Буфер результата затирается и очищается на входе: отказ, случившийся до
	 * отведения буфера, оставлял в нём итог прежней работы - подпись прежних
	 * данных выглядела бы подписью нынешних. Затирается он наравне с буферами
	 * работы по симметричному ключу (4.18): очистка содержимого не гасит, а
	 * расшифровка ключом RSA держит в нём открытый текст
	 */
	// Затираем и очищаем буфер результата
	driver::wipe(result);
	/**
	 * Признак работы выводится наружу отдельно от буфера наравне с разовой
	 * работой по симметричному ключу (4.22): пустой буфер отказом не является,
	 * и судить по нему об удаче нельзя
	 */
	// Признак успешно выполненной работы
	bool outcome = false;
	/**
	 * Контекст библиотеки криптографии заводится в области работы целиком:
	 * заведён он внутри перехвата, и сбой отведения памяти после его заведения
	 * уносил бы работу мимо освобождения - контекст оставался бы висеть
	 */
	// Контекст работы с ключом
	EVP_PKEY_CTX * ctx = nullptr;
	/**
	 * Отсутствующий буфер при заявленном размере отвергается с записью в лог
	 * наравне с работой по симметричному ключу (4.27): молчаливый отказ не давал
	 * отличить негодный довод вызова от отказа самой работы
	 */
	// Если буфер данных не передан, а размер его заявлен
	if((buffer == nullptr) && (size > 0)){
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Data buffer is not passed while its size is declared as %zu octets", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL, size);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Data buffer is not passed while its size is declared as %zu octets", log_t::flag_t::CRITICAL, size);
		#endif
		// Выходим из метода с признаком отказа
		return outcome;
	}
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Если буфер данных и размер данных переданы правильно
		if((buffer != nullptr) || (size == 0)){
			// Получаем ссылку на объект ключа RSA
			const key_rsa_t & key = (* this->_params.key);
			// Если приватный ключ сгенерирован
			if(key.ctx != nullptr){
				// Если ключ является приватным
				if(key.type == key_type_t::PRIVATE){
					// Создаём контекст для шифрования
					ctx = ::EVP_PKEY_CTX_new(key.ctx, nullptr);
					// Если контекст для подписи не создан
					if(ctx == nullptr){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Context allocation failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Context allocation failed", log_t::flag_t::CRITICAL);
						#endif
					// Если контекст для подписи создан
					} else {
						// Если контекст для дешифрования не инициализирован
						if((::EVP_PKEY_decrypt_init(ctx) <= 0) || (::EVP_PKEY_CTX_set_rsa_padding(ctx, RSA_PKCS1_OAEP_PADDING) <= 0) || (::EVP_PKEY_CTX_set_rsa_oaep_md(ctx, ::EVP_sha256()) <= 0) || (::EVP_PKEY_CTX_set_rsa_mgf1_md(ctx, ::EVP_sha256()) <= 0)){
							// Освобождаем контекст для дешифрования
							::EVP_PKEY_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Decrypt init failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Decrypt init failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Размер подписи в байтах
						size_t length = 0;
						// Получаем размер дешифрованных данных
						if(::EVP_PKEY_decrypt(ctx, nullptr, &length, buffer, size) <= 0){
							// Освобождаем контекст для дешифрования
							::EVP_PKEY_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Get decrypted data size failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Get decrypted data size failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Затираем и очищаем буфер результата
						driver::wipe(result);
						// Выделяем память под подпись
						result.resize(length, 0);
						// Получаем дешифрованные данные
						if(::EVP_PKEY_decrypt(ctx, result.data(), &length, buffer, size) <= 0){
							/**
							 * Результат очищается: буфер под него уже отведён и заполнен нулями,
							 * и работа, судящая об удаче по его непустоте, приняла бы нули за
							 * готовый результат
							 */
							// Затираем и очищаем буфер результата
							driver::wipe(result);
							// Освобождаем контекст для дешифрования
							::EVP_PKEY_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Decrypt data failed", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Decrypt data failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Изменяем размер буфера под фактический размер дешифрованных данных
						result.resize(length);
						// Запоминаем признак успешно выполненной работы
						outcome = true;
						// Освобождаем контекст для дешифрования
						::EVP_PKEY_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
					}
				// Если ключ не является приватным
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Unable to decrypt because the key is not private", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Unable to decrypt because the key is not private", log_t::flag_t::CRITICAL);
					#endif
				}
			// Если приватный ключ не сгенерирован или не загружен
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Private key is not generated", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::WARNING);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Private key is not generated", log_t::flag_t::WARNING);
				#endif
			}
		// Если буфер данных или размер данных переданы неправильно
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid buffer or size for decryption", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid buffer or size for decryption", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Буфер результата затирается наравне с прочими отказами (4.18, 5.11):
		 * сбой отведения памяти мог застать работу после того, как в буфер уже
		 * лёг открытый текст либо подпись
		 */
		// Затираем и очищаем буфер результата
		driver::wipe(result);
		// Если контекст работы с ключом заведён
		if(ctx != nullptr)
			// Освобождаем контекст работы с ключом
			::EVP_PKEY_CTX_free(ctx);
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Выводим признак успешно выполненной работы
	return outcome;
}
/**
 * @brief Метод подписания данных приватным ключом RSA
 *
 * @param buffer буфер данных для подписи
 * @param hash   тип хэш-суммы
 * @param result буфер куда следует положить результат
 *
 */
bool awh::Crypto::signWithPrivateKey(const vector <uint8_t> & buffer, const hash_t hash, vector <uint8_t> & result) const noexcept {
	// Вызываем метод подписания данных приватным ключом RSA
	return this->signWithPrivateKey(buffer.data(), buffer.size(), hash, result);
}
/**
 * @brief Метод подписания данных приватным ключом RSA
 *
 * @param buffer буфер данных для подписи
 * @param size   размер данных для подписи
 * @param hash   тип хэш-суммы
 * @param result буфер куда следует положить результат
 *
 */
bool awh::Crypto::signWithPrivateKey(const uint8_t * buffer, const size_t size, const hash_t hash, vector <uint8_t> & result) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	/**
	 * Буфер результата затирается и очищается на входе: отказ, случившийся до
	 * отведения буфера, оставлял в нём итог прежней работы - подпись прежних
	 * данных выглядела бы подписью нынешних. Затирается он наравне с буферами
	 * работы по симметричному ключу (4.18): очистка содержимого не гасит, а
	 * расшифровка ключом RSA держит в нём открытый текст
	 */
	// Затираем и очищаем буфер результата
	driver::wipe(result);
	/**
	 * Признак работы выводится наружу отдельно от буфера наравне с разовой
	 * работой по симметричному ключу (4.22): пустой буфер отказом не является,
	 * и судить по нему об удаче нельзя
	 */
	// Признак успешно выполненной работы
	bool outcome = false;
	/**
	 * Контекст библиотеки криптографии заводится в области работы целиком:
	 * заведён он внутри перехвата, и сбой отведения памяти после его заведения
	 * уносил бы работу мимо освобождения - контекст оставался бы висеть
	 */
	// Контекст работы с ключом
	EVP_MD_CTX * ctx = nullptr;
	/**
	 * Отсутствующий буфер при заявленном размере отвергается с записью в лог
	 * наравне с работой по симметричному ключу (4.27): молчаливый отказ не давал
	 * отличить негодный довод вызова от отказа самой работы
	 */
	// Если буфер данных не передан, а размер его заявлен
	if((buffer == nullptr) && (size > 0)){
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Data buffer is not passed while its size is declared as %zu octets", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL, size);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Data buffer is not passed while its size is declared as %zu octets", log_t::flag_t::CRITICAL, size);
		#endif
		// Выходим из метода с признаком отказа
		return outcome;
	}
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Если буфер данных и размер данных переданы правильно
		if((buffer != nullptr) || (size == 0)){
			// Получаем ссылку на объект ключа RSA
			const key_rsa_t & key = (* this->_params.key);
			// Если приватный ключ сгенерирован
			if(key.ctx != nullptr){
				// Если ключ является приватным
				if(key.type == key_type_t::PRIVATE){
					// Создаём контекст для подписи
					ctx = ::EVP_MD_CTX_new();
					// Если контекст для подписи не создан
					if(ctx == nullptr){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Context allocation failed", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Context allocation failed", log_t::flag_t::CRITICAL);
						#endif
					// Если контекст для подписи создан
					} else {
						// Выбираем хэш-функцию
						const EVP_MD * md = nullptr;
						/**
						 * Определяем тип хэш-суммы
						 */
						switch(static_cast <uint8_t> (hash)){
							// Если тип хэш-суммы указан как MD5
							case static_cast <uint8_t> (hash_t::MD5):
								// Устанавливаем функцию хэширования
								md = ::EVP_md5();
							break;
							// Если тип хэш-суммы указан как SHA1
							case static_cast <uint8_t> (hash_t::SHA1):
								// Устанавливаем функцию хэширования
								md = ::EVP_sha1();
							break;
							// Если тип хэш-суммы указан как SHA224
							case static_cast <uint8_t> (hash_t::SHA224):
								// Устанавливаем функцию хэширования
								md = ::EVP_sha224();
							break;
							// Если тип хэш-суммы указан как SHA256
							case static_cast <uint8_t> (hash_t::SHA256):
								// Устанавливаем функцию хэширования
								md = ::EVP_sha256();
							break;
							// Если тип хэш-суммы указан как SHA384
							case static_cast <uint8_t> (hash_t::SHA384):
								// Устанавливаем функцию хэширования
								md = ::EVP_sha384();
							break;
							// Если тип хэш-суммы указан как SHA512
							case static_cast <uint8_t> (hash_t::SHA512):
								// Устанавливаем функцию хэширования
								md = ::EVP_sha512();
							break;
							// Если ничего не выбрано
							default: {
								// Освобождаем контекст для подписи
								::EVP_MD_CTX_free(ctx);
								// Снимаем указатель освобождённого контекста
								ctx = nullptr;
								/**
								 * Если включён режим отладки
								 */
								#if DEBUG_MODE
									// Записываем ошибку в лог
									this->_log->debug("Unsupported hash type", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
								/**
								 * Если режим отладки не включён
								 */
								#else
									// Записываем ошибку в лог
									this->_log->print("Unsupported hash type", log_t::flag_t::CRITICAL);
								#endif
								// Выходим из метода с признаком отказа
								return outcome;
							}
						}
						// Инициализируем подпись данных
						// Контекст ключа подписи для установки схемы дополнения
						EVP_PKEY_CTX * pctx = nullptr;
						/**
						 * Ступени заведения разнесены порознь тем же порядком, что и у
						 * проверки подписи (5.25): у схемы дополнения своя запись, и
						 * общая подменяла бы названную ею причину
						 */
						// Если заведение контекста подписи не удалось
						if(::EVP_DigestSignInit(ctx, &pctx, md, nullptr, key.ctx) != 1){
							// Освобождаем контекст для подписи
							::EVP_MD_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Digest signature init failed", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Digest signature init failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						// Если установка схемы дополнения подписи не удалась, причину называет она сама
						} else if(!driver::padding(pctx, key.ctx, md, this->_params.padding, this->_log)){
							// Освобождаем контекст для подписи
							::EVP_MD_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Обновляем подпись данными из буфера
						if(::EVP_DigestSignUpdate(ctx, buffer, size) != 1){
							// Освобождаем контекст для подписи
							::EVP_MD_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Digest signature update failed", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Digest signature update failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Размер подписи в байтах
						size_t length = 0;
						// Получаем размер подписи
						if(::EVP_DigestSignFinal(ctx, nullptr, &length) != 1){
							// Освобождаем контекст для подписи
							::EVP_MD_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Digest signature final (get length) failed", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Digest signature final (get length) failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Затираем и очищаем буфер результата
						driver::wipe(result);
						// Выделяем память под подпись
						result.resize(length, 0);
						// Получаем подпись данных
						if(::EVP_DigestSignFinal(ctx, result.data(), &length) != 1){
							/**
							 * Результат очищается: буфер под него уже отведён и заполнен нулями,
							 * и работа, судящая об удаче по его непустоте, приняла бы нули за
							 * готовый результат
							 */
							// Затираем и очищаем буфер результата
							driver::wipe(result);
							// Освобождаем контекст для подписи
							::EVP_MD_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Digest signature final (get signature) failed", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Digest signature final (get signature) failed", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода с признаком отказа
							return outcome;
						}
						// Изменяем размер буфера под фактический размер подписи
						result.resize(length);
						// Запоминаем признак успешно выполненной работы
						outcome = true;
						// Освобождаем контекст для подписи
						::EVP_MD_CTX_free(ctx);
						// Снимаем указатель освобождённого контекста
						ctx = nullptr;
					}
				// Если ключ не является приватным
				} else {
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Unable to sign because the key is not private", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Unable to sign because the key is not private", log_t::flag_t::CRITICAL);
					#endif
				}
			// Если приватный ключ не сгенерирован или не загружен
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Private key is not generated", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::WARNING);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Private key is not generated", log_t::flag_t::WARNING);
				#endif
			}
		// Если буфер данных или размер данных переданы неправильно
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid buffer or size for signing", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid buffer or size for signing", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Буфер результата затирается наравне с прочими отказами (4.18, 5.11):
		 * сбой отведения памяти мог застать работу после того, как в буфер уже
		 * лёг открытый текст либо подпись
		 */
		// Затираем и очищаем буфер результата
		driver::wipe(result);
		// Если контекст работы с ключом заведён
		if(ctx != nullptr)
			// Освобождаем контекст работы с ключом
			::EVP_MD_CTX_free(ctx);
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(size, static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Выводим признак успешно выполненной работы
	return outcome;
}
/**
 * @brief Метод верификации данных публичным ключом RSA
 *
 * @param buffer    буфер данных для верификации
 * @param signature буфер с подписью данных
 * @param hash      тип хэш-суммы
 * @return          результат верификации
 *
 */
bool awh::Crypto::verifyWithPublicKey(const vector <uint8_t> & buffer, const vector <uint8_t> & signature, const hash_t hash) const noexcept {
	// Вызываем метод верификации данных публичным ключом RSA
	return this->verifyWithPublicKey(buffer.data(), buffer.size(), signature, hash);
}
/**
 * @brief Метод верификации данных публичным ключом RSA
 *
 * @param buffer    буфер данных для верификации
 * @param size      размер данных для верификации
 * @param signature буфер с подписью данных
 * @param hash      тип хэш-суммы
 * @return          результат верификации
 *
 */
bool awh::Crypto::verifyWithPublicKey(const uint8_t * buffer, const size_t size, const vector <uint8_t> & signature, const hash_t hash) const noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return false;
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	bool result = false;
	/**
	 * Контекст библиотеки криптографии заводится в области работы целиком:
	 * заведён он внутри перехвата, и сбой отведения памяти после его заведения
	 * уносил бы работу мимо освобождения - контекст оставался бы висеть
	 */
	// Контекст работы с ключом
	EVP_MD_CTX * ctx = nullptr;
	/**
	 * Отсутствующий буфер при заявленном размере отвергается с записью в лог
	 * наравне с работой по симметричному ключу (4.27): молчаливый отказ не давал
	 * отличить негодный довод вызова от отказа самой работы
	 */
	// Если буфер данных не передан, а размер его заявлен
	if((buffer == nullptr) && (size > 0)){
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("Data buffer is not passed while its size is declared as %zu octets", __PRETTY_FUNCTION__, make_tuple(size), log_t::flag_t::CRITICAL, size);
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("Data buffer is not passed while its size is declared as %zu octets", log_t::flag_t::CRITICAL, size);
		#endif
		// Выходим из метода с признаком отказа
		return result;
	}
	/**
	 * Выполняем перехват ошибок
	 */
	try {
		// Если буфер данных и размер данных переданы правильно
		if(((buffer != nullptr) || (size == 0)) && !signature.empty()){
			// Получаем ссылку на объект ключа RSA
			const key_rsa_t & key = (* this->_params.key);
			// Если публичный ключ сгенерирован
			if(key.ctx != nullptr){
				// Создаём контекст для верификации
				ctx = ::EVP_MD_CTX_new();
				// Если контекст для подписи не создан
				if(ctx == nullptr){
					/**
					 * Если включён режим отладки
					 */
					#if DEBUG_MODE
						// Записываем ошибку в лог
						this->_log->debug("Context allocation failed", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
					/**
					 * Если режим отладки не включён
					 */
					#else
						// Записываем ошибку в лог
						this->_log->print("Context allocation failed", log_t::flag_t::CRITICAL);
					#endif
				// Если контекст для подписи создан
				} else {
					// Выбираем хэш-функцию
					const EVP_MD * md = nullptr;
					/**
					 * Определяем тип хэш-суммы
					 */
					switch(static_cast <uint8_t> (hash)){
						// Если тип хэш-суммы указан как MD5
						case static_cast <uint8_t> (hash_t::MD5):
							// Устанавливаем функцию хэширования
							md = ::EVP_md5();
						break;
						// Если тип хэш-суммы указан как SHA1
						case static_cast <uint8_t> (hash_t::SHA1):
							// Устанавливаем функцию хэширования
							md = ::EVP_sha1();
						break;
						// Если тип хэш-суммы указан как SHA224
						case static_cast <uint8_t> (hash_t::SHA224):
							// Устанавливаем функцию хэширования
							md = ::EVP_sha224();
						break;
						// Если тип хэш-суммы указан как SHA256
						case static_cast <uint8_t> (hash_t::SHA256):
							// Устанавливаем функцию хэширования
							md = ::EVP_sha256();
						break;
						// Если тип хэш-суммы указан как SHA384
						case static_cast <uint8_t> (hash_t::SHA384):
							// Устанавливаем функцию хэширования
							md = ::EVP_sha384();
						break;
						// Если тип хэш-суммы указан как SHA512
						case static_cast <uint8_t> (hash_t::SHA512):
							// Устанавливаем функцию хэширования
							md = ::EVP_sha512();
						break;
						// Если ничего не выбрано
						default: {
							// Освобождаем контекст для верификации
							::EVP_MD_CTX_free(ctx);
							// Снимаем указатель освобождённого контекста
							ctx = nullptr;
							/**
							 * Если включён режим отладки
							 */
							#if DEBUG_MODE
								// Записываем ошибку в лог
								this->_log->debug("Unsupported hash type", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
							/**
							 * Если режим отладки не включён
							 */
							#else
								// Записываем ошибку в лог
								this->_log->print("Unsupported hash type", log_t::flag_t::CRITICAL);
							#endif
							// Выходим из метода
							return result;
						}
					}
					// Инициализируем верификацию данных
					// Контекст ключа подписи для установки схемы дополнения
					EVP_PKEY_CTX * pctx = nullptr;
					/**
					 * Отказы проверки подписи разделены по существу: несовпадение подписи - это
					 * законный ответ работы, и записывать его в лог незачем, а сбой заведения
					 * ответом не является вовсе. Прежде оба давали молчаливый отказ, и
					 * неисправность выглядела в точности как подделка.
					 *
					 * Ступени заведения разнесены порознь: прежде всякая из них записывалась как
					 * сбой заведения контекста, тогда как подача данных к заведению уже не
					 * относится. Отказ схемы дополнения своей записи здесь не получает - её
					 * пишет сама установка схемы, и вторая запись была бы лишь шумом
					 */
					// Если контекст проверки подписи не заведён
					if(::EVP_DigestVerifyInit(ctx, &pctx, md, nullptr, key.ctx) != 1){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Error during signature verification context setup", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Error during signature verification context setup", log_t::flag_t::CRITICAL);
						#endif
					// Если схема дополнения подписи не установлена
					} else if(!driver::padding(pctx, key.ctx, md, this->_params.padding, this->_log)){
						/**
						 * Причину отказа записала сама установка схемы дополнения
						 */
					// Если данные к проверке подписи не поданы
					} else if(::EVP_DigestVerifyUpdate(ctx, buffer, size) != 1){
						/**
						 * Если включён режим отладки
						 */
						#if DEBUG_MODE
							// Записываем ошибку в лог
							this->_log->debug("Error during signature verification data update", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL);
						/**
						 * Если режим отладки не включён
						 */
						#else
							// Записываем ошибку в лог
							this->_log->print("Error during signature verification data update", log_t::flag_t::CRITICAL);
						#endif
					// Если контекст проверки подписи заведён
					} else
						// Выполняем верификацию данных
						result = (::EVP_DigestVerifyFinal(ctx, signature.data(), signature.size()) == 1);
					// Освобождаем контекст для верификации
					::EVP_MD_CTX_free(ctx);
					// Снимаем указатель освобождённого контекста
					ctx = nullptr;
				}
			// Если публичный ключ не сгенерирован или не загружен
			} else {
				/**
				 * Если включён режим отладки
				 */
				#if DEBUG_MODE
					// Записываем ошибку в лог
					this->_log->debug("Public key is not generated", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::WARNING);
				/**
				 * Если режим отладки не включён
				 */
				#else
					// Записываем ошибку в лог
					this->_log->print("Public key is not generated", log_t::flag_t::WARNING);
				#endif
			}
		// Если буфер данных или размер данных переданы неправильно
		} else {
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Invalid buffer or size for verification signature", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::WARNING);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Invalid buffer or size for verification signature", log_t::flag_t::WARNING);
			#endif
		}
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		// Если контекст работы с ключом заведён
		if(ctx != nullptr)
			// Освобождаем контекст работы с ключом
			::EVP_MD_CTX_free(ctx);
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, make_tuple(size, signature.size(), static_cast <uint16_t> (hash)), log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
	// Возвращаем результат
	return result;
}
/**
 * @brief Конструктор
 *
 * @param fmk объект фреймворка
 * @param log объект для работы с логами
 *
 */
awh::Crypto::Crypto(const fmk_t * fmk, const log_t * log) noexcept : _fmk(fmk), _log(log) {
	/**
	 * Выполняем отлов ошибок
	 */
	try {
		// Выделяем память под стейт шифрования
		this->_params.state = new state_t();
		// Выделяем память под ключевые данные
		this->_params.key = new key_rsa_t();
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Отведённое до сбоя освобождается: второе отведение, отказав, уносило
		 * работу мимо деструктора - объект собран не был, а первое отведение
		 * оставалось висеть
		 */
		// Если стейт шифрования отведён
		if(this->_params.state != nullptr){
			// Освобождаем память контекста стейта AES-шифрования
			delete this->_params.state;
			// Снимаем указатель освобождённого стейта
			this->_params.state = nullptr;
		}
		// Если ключевые данные отведены
		if(this->_params.key != nullptr){
			// Освобождаем память контекста ключа RSA
			delete this->_params.key;
			// Снимаем указатель освобождённых ключевых данных
			this->_params.key = nullptr;
		}
		// Записываем ошибку в лог
		this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
	}
}
/**
 * @brief Деструктор
 *
 */
awh::Crypto::~Crypto() noexcept {
	/**
	 * Затирание идёт по ёмкости строки, а не по её длине: короткое значение,
	 * записанное поверх длинного, длину укорачивает, а хвост прежнего оставляет
	 * лежать за ней. Ёмкость же строке принадлежит целиком - тем же порядком
	 * гасится и собранное значение в установках (3.9)
	 */
	// Выполняем затирание пароля шифрования
	secret::erase(this->_params.password);
	// Выполняем затирание пароля защиты приватного ключа RSA
	secret::erase(this->_params.passwordRSA);
	/**
	 * Соль затирается наравне с паролями: сама по себе она тайной не является,
	 * но вместе с паролем она составляет всё, из чего выводится ключ
	 */
	// Выполняем затирание соли вывода ключа
	secret::erase(this->_params.salt);
	/**
	 * Ключевые данные освобождают свой ключ RSA собственным деструктором, поэтому
	 * делать это здесь не требуется. Проверка указателя не нужна: сбой отведения
	 * памяти в конструкторе оставляет его пустым, а разрушение пустого указателя
	 * законно и ничего не делает
	 */
	// Освобождаем память контекста ключа RSA
	delete this->_params.key;
	/**
	 * Стейт AES-шифрования освобождает свой контекст и затирает ключ
	 * собственным деструктором, поэтому делать это здесь не требуется
	 */
	// Освобождаем память контекста стейта AES-шифрования
	delete this->_params.state;
}
